using System.Text;

namespace DotObj;

internal sealed partial class Emitter
{
    private void WriteProgramHooks(string output)
    {
        // Optional partial hooks disappear entirely when no runtime provider is
        // linked. Providers own their real process/thread lifecycle and identify
        // non-C++ transfers without bypassing ordinary exception boundaries.
        const string source = """
            // <auto-generated />
            #nullable enable
            namespace Edg.Runtime;

            public static unsafe partial class ObjectProgram
            {
                __OWNED_CLEANUP_HOOKS__

                static partial void Enter();
                static partial void Leave();
                static partial void NormalExit(int status);
                static partial void TryHandleTransfer(global::System.Exception error, ref bool handled, ref int result);
                static partial void ClassifyTransfer(global::System.Exception error, ref bool isRuntimeTransfer);

                // The runtime calls this only after thread finalizers and TSS
                // destructors have finished using the translated TLS storage.
                internal static void ReleaseThreadStorage()
                {
                    __OWNED_TLS_RELEASE__
                }

                public static bool IsRuntimeTransfer(global::System.Exception error)
                {
                    bool result = false;
                    ClassifyTransfer(error, ref result);
                    return result;
                }

                public static int Run(delegate* managed<int> entry)
                    => RunCore(entry, null, 0, null);

                public static int Run(delegate* managed<int, sbyte**, int> entry, int argc, sbyte** argv)
                    => RunCore(null, entry, argc, argv);

                private static int RunCore(delegate* managed<int> entry,
                    delegate* managed<int, sbyte**, int> argumentEntry, int argc, sbyte** argv)
                {
                    Enter();
                    try
                    {
                        try
                        {
                            InitializeLibrary();
                            int result = argumentEntry == null ? entry() : argumentEntry(argc, argv);
                            NormalExit(result);
                            return result;
                        }
                        catch (global::System.Exception error)
                        {
                            bool handled = false;
                            int result = 0;
                            TryHandleTransfer(error, ref handled, ref result);
                            if (!handled)
                            {
                                __UNCAUGHT_CPP__
                                throw;
                            }
                            return result;
                        }
                    }
                    finally
                    {
                        Leave();
                    }
                }
            }
            """;
        string cleanupHooks = linker.Definitions.Any(symbol => symbol.Object.FunctionCleanupStates.ContainsKey(symbol.Entity.Id)) ? """
            // A false first-pass filter marks exceptional exit without selecting
            // a handler. Forced thread exit still runs destructors even though
            // it bypasses source catch/noexcept termination classification.
            public static bool BeginUnwind(global::System.Exception error, ref bool unwinding)
            {
                unwinding = true;
                return false;
            }

            public static bool TerminateCleanupFailure(global::System.Exception error)
            {
                if (!IsRuntimeTransfer(error))
                    global::System.Environment.FailFast("Destructor threw during unwinding", error);
                return false;
            }
            """ : "";
        File.WriteAllText(Path.Combine(output, "Runtime.ObjectProgram.generated.cs"), source.Replace("__UNCAUGHT_CPP__", sharedExceptionProvider && linker.RequiresExceptionProvider ? "if (error is global::Edg.Runtime.CppException) global::System.Environment.FailFast(\"Uncaught C++ exception at program boundary\", error);" : "", StringComparison.Ordinal).Replace("__OWNED_CLEANUP_HOOKS__", cleanupHooks.Replace("\n", "\n    ", StringComparison.Ordinal), StringComparison.Ordinal).Replace("__OWNED_TLS_RELEASE__", tlsRelease.Length == 0 ? "" : Owner + "." + tlsRelease + "();", StringComparison.Ordinal) + "\n", new UTF8Encoding(false));
    }
}
